?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?> - <?= e(APP_NAME) ?></title><link rel="stylesheet" href="assets/css/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><?php include __DIR__.'/includes/header.php'; ?><?php include __DIR__.'/includes/sidebar.php'; ?><main class="main-content"><div class="page-title"><span class="eyebrow">ACCOUNT SETTINGS</span><h1>Your profile</h1></div><section class="panel narrow-panel"><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><?php if($success): ?><div class="alert success"><?= e($success) ?></div><?php endif; ?><form method="post" class="form-stack"><?= csrfField() ?><label>Full name<input name="name" value="<?= e($user['name']) ?>" required></label><label>Username<input value="<?= e($user['username']) ?>" readonly></label><label>Email<input value="<?= e($user['email']) ?>" readonly></label><label>Phone<input name="phone" value="<?= e($user['phone']) ?>"></label><label>Referral code<div class="copy-row"><input id="profileReferral" value="<?= e($user['referral_code']) ?>" readonly><button class="btn ghost" type="button" data-copy-target="profileReferral">Copy</button></div></label><button class="btn primary" type="submit">Save changes</button></form><hr><a class="btn ghost" href="change-password.php">Change password</a></section></main><?php include __DIR__.'/includes/bottom-nav.php'; ?><?php include __DIR__.'/includes/footer.php'; ?><script src="assets/js/app.js"></script></body></html>
